const PHP_PROBE_PATTERN = /(?:^|\/)[^/?#]*\.php$/i;
const SCANNER_PROBE_SEGMENTS = new Set([
    "autoload_classmap.php",
    "dropdown.php",
    "edit.php",
    "h.php",
    "shell20211028.php",
    "wp-admin",
    "wp.php",
    "x.php",
    "zwso.php",
]);
export function isLikelyScannerProbePath(pathname) {
    const normalized = pathname.replace(/^\/+/, "/").toLowerCase();
    if (PHP_PROBE_PATTERN.test(normalized))
        return true;
    return normalized
        .split("/")
        .filter(Boolean)
        .some((segment) => SCANNER_PROBE_SEGMENTS.has(segment));
}
export function getProxyFailureLogLevel(status, method, pathname) {
    if (status === 502 &&
        ["GET", "HEAD"].includes(method.toUpperCase()) &&
        isLikelyScannerProbePath(pathname)) {
        return "warn";
    }
    if (status < 400)
        return "info";
    return status < 500 ? "warn" : "error";
}
